<?php
require_once '../includes/funcoes.php';exigir_admin();
if(isset($_GET['excluir'])){$pdo->prepare("UPDATE produtos SET ativo=0 WHERE id=?")->execute([(int)$_GET['excluir']]);log_acao('Produto desativado');header('Location: produtos.php');exit;}
$rows=$pdo->query("SELECT p.*,c.nome categoria FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.ativo=1 ORDER BY p.id DESC")->fetchAll();$titulo='Produtos';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><div class="d-flex justify-content-between section-title"><h1>Produtos</h1><a class="btn btn-lumia" href="produto_form.php">Novo produto</a></div><div class="panel table-responsive"><table class="table datatable"><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><?=e($p['nome'])?></td><td><?=e($p['categoria']??'—')?></td><td><?=preco($p['preco'])?></td><td><?=$p['estoque']?></td><td><a href="produto_form.php?id=<?=$p['id']?>">Editar</a> · <a class="text-danger" data-confirm="Desativar este produto?" href="?excluir=<?=$p['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require '../includes/footer.php';?>
